import { createSharedComposable } from '@vueuse/core'
import {ref, computed, watch} from 'vue'
import { useStore } from 'vuex';
import { SECRET, CONFIG_MAP } from '@shell/config/types';
import { AGENT_NAMESPACE, KOPILOT_AI_SCHEMA} from '../product';
import { base64Encode } from '@shell/utils/crypto';
export function  useAgents() {
  const store = useStore()
  const aiAgentConfigCRDs = ref([])
  const permissions = computed(() => {
      const canListSecrets = store.getters['management/canList'](SECRET);
      const canListAiAgentCRDS = canListSecrets && store.getters['management/canList'](KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG);
      const configMapschema = store.getters['management/schemaFor'](CONFIG_MAP);
      const canCreateConfigMaps = !!configMapschema?.resourceMethods?.find((verb) => 'PUT' === verb);
      const secretSchema = store.getters['management/schemaFor'](SECRET);
      const canCreateSecrets = !!secretSchema?.resourceMethods?.find((verb) => 'PUT' === verb);
      return {
        list: {
          canListSecrets,
          canListAiAgentCRDS
        },
        create: {
          canCreateConfigMaps,
          canCreateSecrets
        }
      }
  })
  const fetchAgentCRDS = async (errorMap) => {
    if (permissions.value?.list?.canListAiAgentCRDS) {
      try {
      const crds = await store.dispatch(`management/findAll`, {
        type: KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG,
        opt:  { watch: true }
      });

      aiAgentConfigCRDs.value = crds.filter((item) => item.metadata?.labels?.['kopilot.pandaria.io/rancher-ui'] === 'true')
    } catch (err) {
      errorMap.value.set(KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG, err);
      console.warn(`Unable to fetch the ${ KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG } CRD: `, { err });
    }
    }
  }

  const saveAgentsSettings = async (aiAgentsFormData, saveError) => {
    // ai agents config
    let crds = [];
    try {
      crds = await store.dispatch(`management/findAll`, {
        type: KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG,
        opt:  { watch: true }
      });

      crds = crds.filter((item) => item.metadata?.labels['kopilot.pandaria.io/rancher-ui'] === 'true')
    } catch (err) {
      console.warn('Unable to fetch Kopilot AI Agent Config CRDs: ', { err });
      saveError.value.push(err);
    }
    const { data: crdsToSave = [], newSecrets = {}, idKey} = aiAgentsFormData || {};

    for (const [k, v] of Object.entries(newSecrets)) {
      try {
        const password = base64Encode(v.password || '')
        const username = base64Encode(v.username || '')
        const d = {
          password,
          username
        }
        const secret = await store.dispatch('management/create', {
          type:     SECRET,
          metadata: {
            namespace:    AGENT_NAMESPACE,
            generateName: 'ai-agent-auth-',
            labels:       { 'app.kubernetes.io/managed-by': 'kopilot' }
          },
          data: d,
        });

        secret._type = 'kubernetes.io/basic-auth';
        const aiAgentConfigCRD = crdsToSave.find((c) => c[idKey] === k);
        const savedSecret = await secret.save();
        // Update reference to the new secret in the corresponding AI Agent Config CRD
        aiAgentConfigCRD.spec.authenticationType = 'BASIC';
        aiAgentConfigCRD.spec.authenticationSecret = savedSecret.metadata.name;
      } catch (err) {
        console.warn(`Unable to save secret: `, { err });
      }
    }

    for (const crd of crds) {
      const existsInForm = crdsToSave.find((c) => c.metadata.name === crd.metadata.name);

      if (!existsInForm) {
        // Remove existing CRD not present in the form anymore
        try {
          await crd.remove();
        } catch (err) {
          console.warn(`Unable to delete Kopilot AI Agent Config CRD ${ crd.metadata.name }: `, { err });
          saveError.value.push(err);
        }
      }
    }
    for (const crd of crdsToSave) {
      let aiAgentConfigCRD = crds.find((c) => c.metadata.name === crd.metadata.name);

      // Update existing CRD
      if (aiAgentConfigCRD) {
        // Preserve builtIn agents and only update enabled field
        if (aiAgentConfigCRD.spec.builtIn) {
          aiAgentConfigCRD.spec.enabled = crd.spec.enabled;
        } else {
          aiAgentConfigCRD.spec = crd.spec;
        }

      // Create new CRD
      } else {
        aiAgentConfigCRD = await store.dispatch('management/create', {
          type: KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG,
          ...crd,
        });
      }

      // Normalize authenticationSecret
      if (aiAgentConfigCRD.spec.authenticationType === 'BASIC' || aiAgentConfigCRD.spec.authenticationType === 'HEADER') {
        aiAgentConfigCRD.spec.authenticationSecret = aiAgentConfigCRD.spec.authenticationSecret?.replaceAll(`${ AGENT_NAMESPACE }/`, '');
      } else {
        delete aiAgentConfigCRD.spec.authenticationSecret;
      }

      try {
        await aiAgentConfigCRD.save();
      } catch (err) {
        console.warn(`Unable to update Kopilot AI Agent Config CRD ${ crd.metadata.name }: `, { err });
        saveError.value.push(err);
      }
    }
    aiAgentConfigCRDs.value = [...crdsToSave]
  }
  const mergeAiAgentConfigCRDsStatusUpdate = (updatedCrds) => {
    if (!updatedCrds || !aiAgentConfigCRDs.value) {
      return;
    }

    updatedCrds.forEach((storeCrd) => {
      const crd = aiAgentConfigCRDs.value?.find((c) => c.metadata.name === storeCrd.metadata.name);

      if (crd) {
        crd.status = storeCrd.status;
      }
    });
  }
  watch(
    () => store.getters['management/all'](KOPILOT_AI_SCHEMA.AI_AGENT_CONFIG),
    mergeAiAgentConfigCRDsStatusUpdate,
    { deep: true }
  );
  return {
    aiAgentConfigCRDs,
    fetchAgentCRDS,
    saveAgentsSettings
  }
}

export const useSharedAgents = createSharedComposable(useAgents)