// @ts-nocheck
import { importTypes } from '@rancher/auto-import';
import { ActionLocation, IPlugin } from '@shell/core/types';
import extensionRouting from './routing/extension-routing';
import ChatComponent from './pages/Chat.vue';
import Chat from './handlers/chat';
import TemplateMessage from './handlers/hooks/template-message';
import { useSharedQueries } from 'kopilot-ui-components';
import contextStore from './store/context';
import icon from './assets/ai-icon.svg'
import './assets/index.css';


const genSlidingDom = () => {
  const htmlString = '<div id="kopilot-ai-sliding" class="kopilot-ui"><div class="kopilot-ai-icon"></div></div>';
  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlString, 'text/html');
  const element = doc.body.firstElementChild;

  return element;
};
const genBannerButtonDom = () => {
  const htmlString = '<div id="kopilot-ai-banner-button" class="kopilot-ui"><div class="kopilot-ai-icon"></div></div>';
  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlString, 'text/html');
  const element = doc.body.firstElementChild;

  return element;
};

function computeThemeProperties(badge, theme) {
  const out = {
    badge:   { background: '' },
    overlay: {
      background: '#496192',
      color:      'var(--primary-text)',
    },
  };

  const bgColor = getComputedStyle(document.body).getPropertyValue('--body-bg');
  const opacity = theme === 'dark' ? '30%' : '10%';

  (badge?.classList || []).forEach((c) => {
    if (c.startsWith('bg-')) {
      const classId = c.replaceAll('bg-', '');
      const classBgColor = getComputedStyle(document.body).getPropertyValue(`--${ classId }`);

      switch (classId) {
      case 'error':
        if (theme === 'light') {
          out.badge.background = classBgColor;
        }
        break;
      default:
        out.badge.background = `color-mix(in srgb, ${ classBgColor } ${ opacity }, ${ bgColor })`;
        break;
      }
    }
  });

  return out;
}
const STATES = ['info', 'warning', 'error', 'success']
const getState = (target) => {
  return target.classList.values().find((item) => STATES.includes(item));
}
// Init the package
export default function(plugin: IPlugin, { store }: any): void {
  // Auto-import model, detail, edit from the folders
  importTypes(plugin);

  // Provide plugin metadata from package.json
  plugin.metadata = require('./package.json');

  // Load a product
  plugin.addProduct(require('./product'));
  // Add Vue Routes
  plugin.addRoutes(extensionRouting);
  // Register the Chat component
  plugin.register('component', 'KopilotChatComponent', ChatComponent);
  // Open chat window action
  plugin.addAction(
    ActionLocation.HEADER,
    {},
    {
      tooltipKey: 'kopilot.action.openChat',
      // shortcut:   {
      //   windows: ['alt', 'k'],
      //   mac:     ['meta', 'shift', 'k']
      // },
      svg: require('./assets/ai-icon.svg'),
      // icon:       'i-custom-toy?mask',
      invoke:     () => {
        Chat.isOpen(store) ? Chat.close(store) : Chat.open(store);
      },
    }
  );
  plugin.addDashboardStore(contextStore.config.namespace, contextStore.specifics, contextStore.config);

  let hasLizAi = false;

  store.watch((state) => {
    return state.uiplugins.plugins.find((p) => p.name === 'rancher-ai-ui');
  }, (ui) => {
    if (ui) {
      hasLizAi = true;

      return;
    }
    hasLizAi = false;
  }, { immediate: true });

  const theme = store.getters['prefs/theme'];

  let appDom = document.body.querySelector('#app');

  const controller = new AbortController();
  let activeHookId = null;
  let slidingDom = genSlidingDom();
  let bannerButtonDom = genBannerButtonDom();
  let mutationObserver = null;
  let currentWith = null
  let cleanBadgeResource = null
  mutationObserver = new  MutationObserver((mutations) => {
    mutations.forEach(mutation => {
      if (mutation.type === 'attributes' && 
          mutation.attributeName === 'style') {
        const style = getComputedStyle(document.documentElement);
        const w = style.getPropertyValue('--wm-vr-width');
        if (w !== currentWith) {
          currentWith = w;
          slidingDom?.remove();
        }
      }
    });
  });
  mutationObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['style']
  })
  const handleScroll = (e) => {
    if (e.target.tagName === 'MAIN' && e.target.classList.contains('main-layout')) {
      slidingDom?.remove();
    }
  };
  appDom.addEventListener('scroll', handleScroll, true);
  plugin.addUninstallHook(() => {
    controller?.abort();
    appDom.removeEventListener('scroll', handleScroll);
    mutationObserver?.disconnect()
    appDom = null;
    slidingDom?.remove();
    bannerButtonDom?.remove()
    slidingDom = null;
    bannerButtonDom = null;
    mutationObserver = null;
    cleanBadgeResource?.();
    cleanBadgeResource = null;
  });
  const { queries } = useSharedQueries();
  const handleClick = (e) => {
    const hookId = e.currentTarget.dataset.uxContextHookId;
    const ctx = store.getters['ui-context/all'].find((c) => c.hookId === hookId);
    const globalCtx = store.getters['kopilot-ui/context/all'];
    const message = TemplateMessage.fill(store, ctx, globalCtx);

    if (!queries.value.has(hookId)) {
      queries.value.set(hookId, message);
    }
    if (!Chat.isOpen(store)) {
      Chat.open(store);
    }
  }
  slidingDom.addEventListener('click', handleClick, { signal: controller.signal });
  bannerButtonDom.addEventListener('click', handleClick, { signal: controller.signal });
  const processSlideBanner = (badge, closest) => {
    const rect = badge.getBoundingClientRect();
    const style = getComputedStyle(badge);
    const {
      badge: badgeProps,
      overlay: overlayProps
    } = computeThemeProperties(badge, theme);

    badge.style.zIndex = Math.max(parseInt(badge.style.zIndex || '0'), 12).toString();
    badge.style.background = badgeProps.background;
    Array.from(badge.attributes).filter((a) => a.name.startsWith('data-v-')).forEach((a) => {
      slidingDom.setAttribute(a.name, a.value);
    });
    // slidingDom.setAttribute('data-ux-context-hook-id', activeHookId);
    slidingDom.dataset.uxContextHookId = activeHookId;
    slidingDom.classList.add('badge-state');
    slidingDom.style.top = `${ rect.top }px`;
    slidingDom.style.left = `${ rect.left }px`;
    slidingDom.style.height = `${ rect.height }px`;
    slidingDom.style.width = `${ rect.width }px`;
    slidingDom.style.fontSize = style.fontSize;
    slidingDom.style.zIndex = '10';
    setTimeout(() => {
      const w = parseInt(style.fontSize) * 1.8 + 20;

      slidingDom.style.width = `${ rect.width + w - parseFloat(style.marginRight) - parseFloat(style.marginLeft) }px`;
      if (hasLizAi) {
        slidingDom.style.left = `${ rect.left - w }px`;
        slidingDom.style.justifyContent = 'flex-start';
      } else {
        slidingDom.style.left = `${ rect.left }px`;
        slidingDom.style.justifyContent = 'flex-end';
      }
    }, 10);
    closest.parentElement.appendChild(slidingDom);
  }
  const procecssBannerButton = (banner, closest) => {
    const rect = banner.getBoundingClientRect();
    const style = getComputedStyle(banner);
    const state = getState(closest) ?? 'success'
    bannerButtonDom.style.zIndex = Math.max(parseInt(banner.style.zIndex || '0'), 12).toString();
    bannerButtonDom.style.backgroundColor = `var(--${state})`;
    bannerButtonDom.style.color = `${state === 'error' ? 'var(--on-error-banner)' : `var(--${ state }-text)`}`;
    Array.from(banner.attributes).filter((a) => a.name.startsWith('data-v-')).forEach((a) => {
      bannerButtonDom.setAttribute(a.name, a.value);
    });
    const height = 24;
    const rightOffset = Math.max(8, window.innerWidth - rect.right + 8);
    const gap = 8;
    const viewportPadding = 8;
    let top = Math.round(rect.bottom - height - gap);

    top = Math.min(Math.max(viewportPadding, top), window.innerHeight - height - viewportPadding);
    bannerButtonDom.dataset.uxContextHookId = activeHookId;
    bannerButtonDom.classList.add('state-banner');
    if (hasLizAi) {
      bannerButtonDom.style.top = `${ top - 24 }px`;
    } else {
      bannerButtonDom.style.top = `${ top }px`;
    }
    bannerButtonDom.style.right = `${ rightOffset }px`;
    bannerButtonDom.style.height = `${ height }px`;
    bannerButtonDom.style.width = `${ height }px`;
    bannerButtonDom.style.fontSize = style.fontSize;
    bannerButtonDom.style.zIndex = '10';
    closest.appendChild(bannerButtonDom);
  }
  const processBadgeChange = (badge) => {
    let lastContainerRect = badge.getBoundingClientRect();
    const onBadgePosChange = () => {
      try {
        const r = badge.getBoundingClientRect();

        if (r.top !== lastContainerRect.top || r.left !== lastContainerRect.left) {
          // parent moved -> remove overlays for this target, immediately
          slidingDom?.remove()
        } else {
          lastContainerRect = r;
        }
      } catch (e) {
        console.warn('Error checking container position change', e);
      }
    };
    const containerRO = new ResizeObserver(onBadgePosChange);
    containerRO.observe(badge);
    const containerMO = new MutationObserver(onBadgePosChange);
    containerMO.observe(badge, {
      attributes:      true,
      attributeFilter: ['style', 'class']
    });
    return () => {
      containerRO.disconnect();
      containerMO.disconnect();
    }
  }
  appDom.addEventListener('mouseover', (e) => {
    const target = e.target;
    const closest = target.closest('[ux-context-hook-id]');
    const id = closest?.getAttribute('ux-context-hook-id');

    if (activeHookId && (!id || activeHookId !== id)) {
      if ((target === slidingDom || target.closest('#kopilot-ai-sliding')) || (target === bannerButtonDom || target.closest('#kopilot-ai-banner-button'))) {
        return;
      } else {
        activeHookId = null;
        slidingDom.remove();
        bannerButtonDom.remove();
        cleanBadgeResource?.();
        cleanBadgeResource = null
      }
    }
    if (id && ( !activeHookId || activeHookId !== id)) {
      activeHookId = id;
      const badge = closest.classList.contains('badge-state') ? closest : closest.querySelector('.badge-state');
      if (badge) {
        processSlideBanner(badge, closest);
        cleanBadgeResource?.();
        cleanBadgeResource = processBadgeChange(badge);
        return;
      }
      const banner = closest.classList.contains('state-banner') ? closest : closest.querySelector('.state-banner');
      if (banner) {
        procecssBannerButton(banner, closest);
        return;
      }
    }
  }, { signal: controller.signal });
}
